package com.termux.app.workspace;
import android.app.*;import android.content.*;import android.net.Uri;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class WorkspaceGalleryPickerTest {
 @Test public void intentsUseNativeMediaPickerOrMediaOnlyDocumentFallback(){Intent modern=WorkspaceGalleryPicker.intent(4,true);assertEquals("android.provider.action.PICK_IMAGES",modern.getAction());assertEquals(4,modern.getIntExtra("android.provider.extra.PICK_IMAGES_MAX",0));Intent old=WorkspaceGalleryPicker.intent(3,false);assertEquals(Intent.ACTION_OPEN_DOCUMENT,old.getAction());assertArrayEquals(new String[]{"image/*","video/*"},old.getStringArrayExtra(Intent.EXTRA_MIME_TYPES));assertTrue(old.getBooleanExtra(Intent.EXTRA_ALLOW_MULTIPLE,false));}
 @Test public void selectionsDeduplicateContentUrisAndRejectNonMediaPathsOrExcessCount(){Uri one=Uri.parse("content://photos/1"),two=Uri.parse("content://photos/2");Intent data=new Intent().setData(one);ClipData clips=ClipData.newRawUri("photos",one);clips.addItem(new ClipData.Item(two));data.setClipData(clips);assertEquals(Arrays.asList(one,two),WorkspaceGalleryPicker.selection(data,4));try{WorkspaceGalleryPicker.selection(data,1);fail();}catch(IllegalArgumentException expected){}try{WorkspaceGalleryPicker.selection(new Intent().setData(Uri.parse("file:///root/private")),4);fail();}catch(IllegalArgumentException expected){}}
 @Test public void cancellationAndDuplicateResultsNeverAttachFiles(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();WorkspaceGalleryPicker picker=new WorkspaceGalleryPicker(a);AtomicInteger callbacks=new AtomicInteger();picker.pick(4,uris->{assertTrue(uris.isEmpty());callbacks.incrementAndGet();});int request=Shadows.shadowOf(a).getNextStartedActivityForResult().requestCode;assertTrue(picker.result(request,Activity.RESULT_CANCELED,null));assertTrue(picker.result(request,Activity.RESULT_OK,new Intent().setData(Uri.parse("content://photos/1"))));assertEquals(1,callbacks.get());picker.close();}

 @Test public void excessiveSelectionReportsLimitAndClosedPickerIgnoresLateResult(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();WorkspaceGalleryPicker picker=new WorkspaceGalleryPicker(a);AtomicInteger calls=new AtomicInteger();picker.pick(1,uris->{assertTrue(uris.isEmpty());calls.incrementAndGet();});int request=Shadows.shadowOf(a).getNextStartedActivityForResult().requestCode;ClipData clips=ClipData.newRawUri("photos",Uri.parse("content://photos/1"));clips.addItem(new ClipData.Item(Uri.parse("content://photos/2")));Intent selected=new Intent();selected.setClipData(clips);picker.result(request,Activity.RESULT_OK,selected);assertEquals(1,calls.get());assertNotNull(org.robolectric.shadows.ShadowToast.getTextOfLatestToast());picker.pick(1,uris->fail("Closed picker must ignore a late result"));request=Shadows.shadowOf(a).getNextStartedActivityForResult().requestCode;picker.close();assertTrue(picker.result(request,Activity.RESULT_OK,new Intent().setData(Uri.parse("content://photos/1"))));}
}
